#!/usr/bin/env node
// Synthetic ground-truth corpus (Common Setup §"Build the synthetic ground-truth
// corpus first"). Twenty shapes generated BY STROKING a known centerline, so the
// true answer is known and centerline error is measurable — not just
// reconstruction error.
//
// Each case writes:
//   debug/tegaki/synth/<nn>-<name>.svg        the filled shape (input)
//   debug/tegaki/synth/<nn>-<name>.truth.json the source centerline(s) + width
//
// The fill is produced by rendering the stroked path and converting it to a fill
// via our own stroker (offset polygon with round/butt/square caps and joins), so
// no external tool is needed and the result is deterministic.

import { writeFileSync, mkdirSync } from 'node:fs';
import { flattenPathData } from './bezier.js';

const OUT = 'debug/tegaki/synth';

// ── a minimal stroker: centerline polyline -> filled outline polygon ───────
function offsetSide(pts, r, cap, join) {
  const out = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const a = pts[i];
    const b = pts[i + 1];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len = Math.hypot(dx, dy);
    if (len === 0) continue;
    const nx = (-dy / len) * r;
    const ny = (dx / len) * r;
    if (out.length > 0 && join === 'round') {
      // arc around `a` from the previous normal to this one
      const prev = out[out.length - 1];
      const a0 = Math.atan2(prev.y - a.y, prev.x - a.x);
      const a1 = Math.atan2(ny, nx);
      let d = a1 - a0;
      while (d > Math.PI) d -= 2 * Math.PI;
      while (d < -Math.PI) d += 2 * Math.PI;
      const steps = Math.max(1, Math.ceil(Math.abs(d) / 0.2));
      for (let s = 1; s < steps; s++) {
        const t = a0 + (d * s) / steps;
        out.push({ x: a.x + Math.cos(t) * r, y: a.y + Math.sin(t) * r });
      }
    }
    out.push({ x: a.x + nx, y: a.y + ny });
    out.push({ x: b.x + nx, y: b.y + ny });
  }
  return out;
}

function capPoints(from, to, r, cap) {
  // Cap at `to`, coming from `from`. Returns points from the +normal side to the -normal side.
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const len = Math.hypot(dx, dy) || 1;
  const ux = dx / len;
  const uy = dy / len;
  const nx = -uy * r;
  const ny = ux * r;
  if (cap === 'butt') return [];
  if (cap === 'square') {
    return [
      { x: to.x + nx + ux * r, y: to.y + ny + uy * r },
      { x: to.x - nx + ux * r, y: to.y - ny + uy * r },
    ];
  }
  const pts = [];
  const a0 = Math.atan2(ny, nx);
  const steps = 12;
  for (let s = 1; s < steps; s++) {
    const t = a0 - (Math.PI * s) / steps;
    pts.push({ x: to.x + Math.cos(t) * r, y: to.y + Math.sin(t) * r });
  }
  return pts;
}

/** Stroke an open polyline into a closed fill polygon. */
export function strokeToFill(pts, width, cap = 'round', join = 'round') {
  const r = width / 2;
  const closed = Math.hypot(pts[0].x - pts[pts.length - 1].x, pts[0].y - pts[pts.length - 1].y) < 1e-9;
  if (closed) {
    const ring = pts.slice(0, -1);
    const loop = [...ring, ring[0], ring[1]];
    const outer = offsetSide(loop, r, cap, join).slice(0, -2);
    const inner = offsetSide([...loop].reverse(), r, cap, join).slice(0, -2);
    return [outer, inner];
  }
  const left = offsetSide(pts, r, cap, join);
  const right = offsetSide([...pts].reverse(), r, cap, join);
  const capEnd = capPoints(pts[pts.length - 2], pts[pts.length - 1], r, cap);
  const capStart = capPoints(pts[1], pts[0], r, cap);
  return [[...left, ...capEnd, ...right, ...capStart]];
}

const toD = (rings) => rings.map((ring) => ring.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x.toFixed(3)} ${p.y.toFixed(3)}`).join(' ') + ' Z').join(' ');

function svgWrap(body, w = 300, h = 200) {
  return (
    `<?xml version="1.0" encoding="UTF-8" standalone="no"?>\n` +
    `<svg xmlns="http://www.w3.org/2000/svg" version="1.1" viewBox="0 0 ${w} ${h}">\n${body}\n</svg>\n`
  );
}

const line = (x1, y1, x2, y2, n = 2) =>
  Array.from({ length: n + 1 }, (_, i) => ({ x: x1 + ((x2 - x1) * i) / n, y: y1 + ((y2 - y1) * i) / n }));

const arc = (cx, cy, r, a0, a1, n = 48) =>
  Array.from({ length: n + 1 }, (_, i) => {
    const t = a0 + ((a1 - a0) * i) / n;
    return { x: cx + Math.cos(t) * r, y: cy + Math.sin(t) * r };
  });

function fromPath(d) {
  return flattenPathData(d, 0.05)[0];
}

const W = 20;

export const CASES = [
  { name: 'horizontal-line', paths: [line(50, 100, 250, 100)] },
  { name: 'diagonal-line', paths: [line(50, 40, 250, 160)] },
  { name: 'circular-arc', paths: [arc(150, 150, 90, Math.PI, 2 * Math.PI)] },
  { name: 's-curve', paths: [fromPath('M 40 150 C 100 40 200 260 260 150')] },
  { name: 'tight-u', paths: [fromPath('M 90 40 L 90 110 A 40 40 0 0 0 170 110 L 170 40')] },
  { name: 'closed-loop', paths: [arc(150, 100, 70, 0, 2 * Math.PI)] },
  { name: 'round-cap', paths: [line(60, 100, 240, 100)], cap: 'round' },
  { name: 'butt-cap', paths: [line(60, 100, 240, 100)], cap: 'butt' },
  { name: 'square-cap', paths: [line(60, 100, 240, 100)], cap: 'square' },
  { name: 'round-join', paths: [[{ x: 60, y: 160 }, { x: 150, y: 40 }, { x: 240, y: 160 }]], join: 'round' },
  { name: 'bevel-join', paths: [[{ x: 60, y: 160 }, { x: 150, y: 40 }, { x: 240, y: 160 }]], join: 'bevel' },
  { name: 'miter-join', paths: [[{ x: 60, y: 160 }, { x: 150, y: 40 }, { x: 240, y: 160 }]], join: 'miter' },
  { name: 'x-crossing-separate', paths: [line(50, 40, 250, 160), line(50, 160, 250, 40)], separate: true },
  { name: 'x-crossing-union', paths: [line(50, 40, 250, 160), line(50, 160, 250, 40)] },
  { name: 't-junction', paths: [line(50, 60, 250, 60), line(150, 60, 150, 180)] },
  { name: 'y-junction', paths: [line(150, 180, 150, 100), line(150, 100, 70, 30), line(150, 100, 230, 30)] },
  { name: 'parallel-close', paths: [line(50, 85, 250, 85), line(50, 115, 250, 115)] },
  { name: 'self-overlap', paths: [fromPath('M 80 100 A 45 45 0 1 1 200 100 L 120 100')] },
  { name: 'variable-width', paths: [line(50, 100, 250, 100)], variable: true },
  { name: 'noisy-boundary', paths: [line(50, 100, 250, 100)], noise: 1.6 },
];

function jitterRings(rings, amp, seed) {
  // Deterministic pseudo-noise, so the corpus is reproducible.
  let s = seed;
  const rnd = () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 0xffffffff - 0.5;
  };
  return rings.map((r) => r.map((p) => ({ x: p.x + rnd() * 2 * amp, y: p.y + rnd() * 2 * amp })));
}

function variableRings(pts, w0, w1) {
  const r0 = w0 / 2;
  const r1 = w1 / 2;
  const left = [];
  const right = [];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[Math.max(0, i - 1)];
    const b = pts[Math.min(pts.length - 1, i + 1)];
    const dx = b.x - a.x;
    const dy = b.y - a.y;
    const len = Math.hypot(dx, dy) || 1;
    const t = i / (pts.length - 1);
    const r = r0 + (r1 - r0) * t;
    left.push({ x: pts[i].x + (-dy / len) * r, y: pts[i].y + (dx / len) * r });
    right.push({ x: pts[i].x - (-dy / len) * r, y: pts[i].y - (dx / len) * r });
  }
  return [[...left, ...right.reverse()]];
}

export function generate(outDir = OUT) {
  mkdirSync(outDir, { recursive: true });
  const manifest = [];

  CASES.forEach((c, i) => {
    const nn = String(i + 1).padStart(2, '0');
    const cap = c.cap ?? 'round';
    const join = c.join ?? 'round';
    let body;
    let truthWidth = W;

    if (c.variable) {
      const pts = line(50, 100, 250, 100, 40);
      const rings = variableRings(pts, 10, 30);
      body = `<path fill="#222222" d="${toD(rings)}"/>`;
      truthWidth = [10, 30];
    } else if (c.separate) {
      body = c.paths
        .map((p) => `<path fill="#222222" d="${toD(strokeToFill(p, W, cap, join))}"/>`)
        .join('\n');
    } else {
      let rings = c.paths.flatMap((p) => strokeToFill(p, W, cap, join));
      if (c.noise) rings = jitterRings(rings, c.noise, 12345 + i);
      body = `<path fill="#222222" d="${toD(rings)}"/>`;
    }

    const file = `${outDir}/${nn}-${c.name}.svg`;
    writeFileSync(file, svgWrap(body));
    const truth = {
      case: c.name,
      index: i + 1,
      width: truthWidth,
      cap,
      join,
      separateElements: !!c.separate,
      centerlines: (c.variable ? [line(50, 100, 250, 100, 40)] : c.paths).map((p) => p.map((q) => ({ x: +q.x.toFixed(3), y: +q.y.toFixed(3) }))),
    };
    writeFileSync(`${outDir}/${nn}-${c.name}.truth.json`, JSON.stringify(truth, null, 1));
    manifest.push({ index: i + 1, name: c.name, svg: file });
  });

  writeFileSync(`${outDir}/manifest.json`, JSON.stringify(manifest, null, 1));
  return manifest;
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const m = generate(process.argv[2] || OUT);
  console.log(`wrote ${m.length} synthetic cases`);
}
